package me.minis.ledger;
import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
/** Bounded pages, SQL merchant aggregates, persistent row versions and disk-backed selections. */
public final class LedgerQuery {
 public static final int SIZE=40;
 static final String NAME="("+MerchantIdentity.groupSql("merchant")+")";
 static final String GROUP="CASE WHEN "+NAME+" IN ('','支付','转账','红包','付款','收款','未识别','未知商户','其他','购物订单','支付宝','微信','云闪付','手动') THEN 'single:'||_id ELSE kind||':'||"+NAME+" END";
 static final String COLS="e._id,e.time,e.source,e.kind,e.cents,e.merchant,e.category,e.status,v.rev";
 public static void install(SQLiteDatabase db){
  db.execSQL("CREATE TABLE IF NOT EXISTS ui_version(id INTEGER PRIMARY KEY,rev INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS ui_changes(seq INTEGER PRIMARY KEY AUTOINCREMENT,id INTEGER,ot INTEGER,nt INTEGER,os TEXT,ns TEXT,og TEXT,ng TEXT)");
  db.execSQL("CREATE INDEX IF NOT EXISTS ui_change_id ON ui_changes(id,seq)");
  db.execSQL("INSERT OR IGNORE INTO ui_version SELECT _id,0 FROM entries");
  db.execSQL("CREATE TABLE IF NOT EXISTS ui_selection(token TEXT,id INTEGER,rev INTEGER,PRIMARY KEY(token,id))");
  String og=GROUP.replace("merchant","old.merchant").replace("kind","old.kind").replace("_id","old._id"),ng=GROUP.replace("merchant","new.merchant").replace("kind","new.kind").replace("_id","new._id");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS ui_insert AFTER INSERT ON entries BEGIN INSERT INTO ui_changes(id,nt,ns,ng) VALUES(new._id,new.time,new.status,"+ng+"); INSERT OR REPLACE INTO ui_version VALUES(new._id,last_insert_rowid()); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS ui_update AFTER UPDATE ON entries BEGIN INSERT INTO ui_changes(id,ot,nt,os,ns,og,ng) VALUES(new._id,old.time,new.time,old.status,new.status,"+og+","+ng+"); INSERT OR REPLACE INTO ui_version VALUES(new._id,last_insert_rowid()); END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS ui_delete AFTER DELETE ON entries BEGIN INSERT INTO ui_changes(id,ot,os,og) VALUES(old._id,old.time,old.status,CASE WHEN old.status='ignored' THEN '' ELSE "+og+" END); DELETE FROM ui_version WHERE id=old._id; END");
  db.execSQL("CREATE TRIGGER IF NOT EXISTS ui_trim AFTER INSERT ON ui_changes WHEN new.seq%512=0 BEGIN DELETE FROM ui_changes WHERE seq<new.seq-4096; END");
 }
 static final String PROCESS=UUID.randomUUID().toString();
 final LedgerDb helper; final String token=PROCESS+":"+UUID.randomUUID().toString();
 final Map<String,Map<String,String>> delivered=new HashMap<>();
 public LedgerQuery(LedgerDb db){helper=db;db.getWritableDatabase().delete("ui_selection","token NOT LIKE ?",new String[]{PROCESS+":%"});}
 static class Filter{String where;List<String> args=new ArrayList<>();Filter(JSONObject q)throws JSONException{
  String status=q.optString("status","confirmed");if(!Arrays.asList("confirmed","review").contains(status))throw new JSONException("状态不合法");where="status=?";args.add(status);
  if(!q.optBoolean("all",false)){where+=" AND time>=? AND time<?";args.add(""+q.getLong("start"));args.add(""+q.getLong("end"));}
  String kind=q.optString("kind","all");if(!kind.equals("all")){if(!Arrays.asList("expense","income","refund").contains(kind))throw new JSONException("类型不合法");where+=" AND kind=?";args.add(kind);}
  String text=q.optString("q","").trim().toLowerCase(Locale.ROOT);if(text.length()>200)throw new JSONException("关键词过长");if(!text.isEmpty()){where+=" AND (instr(lower(merchant||' '||category||' '||source),?)>0";args.add(text);where+=" OR lower("+NAME+")=?";args.add(MerchantIdentity.groupName(text));long amount=SearchAmount.parse(text);if(amount>=0){where+=" OR cents=?";args.add(""+amount);}for(Map.Entry<String,String> p:labels().entrySet())if(p.getValue().toLowerCase(Locale.ROOT).contains(text)){where+=" OR source=?";args.add(p.getKey());}where+=")";}
  String category=q.optString("category","");if(!category.isEmpty()){if(!Arrays.asList(LedgerDb.CATEGORIES).contains(category))throw new JSONException("分类不合法");where+=" AND _id IN (SELECT _id FROM ledger_parts WHERE part_category=?)";args.add(category);}
  long min=-1,max=-1;for(String key:new String[]{"minAmount","maxAmount"}){String input=q.optString(key,"").trim();if(input.isEmpty())continue;long cents=SearchAmount.parse(input);if(cents<0)throw new JSONException("金额须为非负数，最多两位小数");if(key.equals("minAmount"))min=cents;else max=cents;where+=" AND cents"+(key.equals("minAmount")?">=":"<=")+"?";args.add(""+cents);}if(min>=0&&max>=0&&min>max)throw new JSONException("最低金额不能高于最高金额");
  if(q.optBoolean("counted",false)){where+=" AND excluded=0 AND time<?";args.add(""+WidgetPeriods.throughToday(System.currentTimeMillis()));}
  if(q.has("group")){where+=" AND ("+GROUP+")=?";args.add(q.getString("group"));}
 }String[] args(){return args.toArray(new String[0]);}}
 static Map<String,String> labels(){Map<String,String> out=new HashMap<>(LedgerDb.knownLabels());for(int i=0;i<LedgerDb.SOURCES.length;i++){out.put(LedgerDb.SOURCES[i],LedgerDb.label(LedgerDb.SOURCES[i]));out.put(LedgerDb.SOURCES[i]+":screen",LedgerDb.label(LedgerDb.SOURCES[i]+":screen"));}out.put("manual","手动");return out;}
 public JSONObject page(JSONObject q)throws Exception{
  int page=q.optInt("page",0);if(page<0||page>1000000)throw new JSONException("页码不合法");Filter f=new Filter(q);boolean groups=q.optBoolean("groups",false);SQLiteDatabase db=helper.getReadableDatabase();db.beginTransactionNonExclusive();try{
   long total=DatabaseUtils.longForQuery(db,"SELECT count(*) FROM entries WHERE "+f.where,f.args());JSONArray rows=new JSONArray();String limit=" LIMIT "+SIZE+" OFFSET "+((long)page*SIZE);
   String scope=q.optString("status","confirmed").equals("review")?"review":"book",pick="CASE WHEN _id IN (SELECT id FROM ui_selection WHERE token=?) THEN 1 ELSE 0 END";
   String sql=groups?"SELECT ("+GROUP+") AS g,"+NAME+" AS name,kind,count(*) AS count,sum(cents) AS cents,max(time) AS time,max(_id) AS tie,sum(picked),CASE WHEN count(DISTINCT category)=1 THEN min(category) ELSE '其他' END AS category,count(DISTINCT category) AS categoryCount,min(source) AS source,min(merchant) AS merchant,max(excluded) AS excluded,max(rev) AS rev FROM (SELECT _id,time,kind,merchant,cents,category,source,excluded,COALESCE(v.rev,0) AS rev,"+pick+" AS picked FROM entries LEFT JOIN ui_version v ON v.id=entries._id WHERE "+f.where+") GROUP BY g ORDER BY time DESC,tie DESC"+limit:"SELECT "+COLS+",e.picked,e.excluded FROM (SELECT _id,time,source,kind,cents,merchant,category,status,excluded,"+pick+" AS picked FROM entries WHERE "+f.where+" ORDER BY time DESC,_id DESC"+limit+") e JOIN ui_version v ON v.id=e._id ORDER BY e.time DESC,e._id DESC";
   List<String> queryArgs=new ArrayList<>();queryArgs.add(token+scope);queryArgs.addAll(f.args);
   try(Cursor c=db.rawQuery(sql,queryArgs.toArray(new String[0]))){while(c.moveToNext()){JSONObject row=new JSONObject();if(groups){row.put("singleId",c.getLong(3)==1?c.getLong(6):0).put("key",c.getString(0)).put("name",c.getString(1)).put("kind",c.getString(2)).put("count",c.getLong(3)).put("cents",c.getLong(4)).put("time",c.getLong(5)).put("selected",c.getLong(7)).put("category",c.getString(8)).put("categoryCount",c.getLong(9)).put("source",c.getString(10)).put("merchant",c.getString(11)).put("excluded",c.getLong(12)).put("rev",c.getLong(13)).put("label",LedgerDb.label(c.getString(10)));}else{for(int i=0;i<8;i++)row.put(c.getColumnName(i),i==0||i==1||i==4?c.getLong(i):c.getString(i));row.put("rev",c.getLong(8)).put("selected",c.getLong(9)).put("excluded",c.getLong(10)).put("label",LedgerDb.label(c.getString(2)));}rows.put(row);}}
   long groupTotal=groups?DatabaseUtils.longForQuery(db,"SELECT count(*) FROM (SELECT 1 FROM entries WHERE "+f.where+" GROUP BY "+GROUP+")",f.args()):total;
   // Native bounded-page diff: unchanged records never cross the bridge again.
   String cache=q.toString();Map<String,String> old=delivered.get(cache),next=new LinkedHashMap<>();JSONArray order=new JSONArray(),changed=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String key=groups?r.getString("key"):""+r.getLong("_id");order.put(key);String value=groups?r.getLong("count")+"|"+r.getLong("cents")+"|"+r.getLong("time")+"|"+r.getString("name")+"|"+r.getString("category")+"|"+r.getLong("categoryCount")+"|"+r.getLong("singleId")+"|"+r.getLong("rev"):""+r.getLong("rev");value+="|"+r.getLong("selected");next.put(key,value);if(old==null||!value.equals(old.get(key)))changed.put(r);}if(delivered.size()>256)delivered.clear();delivered.put(cache,next);
   JSONObject out=new JSONObject().put("rows",changed).put("order",order).put("total",total).put("items",groupTotal).put("page",page).put("more",((long)page+1)*SIZE<groupTotal).put("revision",revision(db));db.setTransactionSuccessful();return out;
  }finally{db.endTransaction();}
 }
 public JSONObject overview(JSONObject input)throws Exception{SQLiteDatabase db=helper.getReadableDatabase();db.beginTransactionNonExclusive();try{JSONObject value=FinanceQueries.overview(db,input);db.setTransactionSuccessful();return value;}finally{db.endTransaction();}}
 public static long revision(SQLiteDatabase db){return DatabaseUtils.longForQuery(db,"SELECT COALESCE(max(seq),0) FROM ui_changes",null);}
 public JSONObject changes(long since)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();long rev=revision(db);JSONArray rows=new JSONArray();long min=DatabaseUtils.longForQuery(db,"SELECT COALESCE(min(seq),0) FROM ui_changes",null);boolean reset=since<min-1;try(Cursor c=db.rawQuery("SELECT ot,nt,os,ns,og,ng FROM ui_changes WHERE seq>? ORDER BY seq LIMIT 201",new String[]{""+since})){while(c.moveToNext()){JSONObject r=new JSONObject();for(int i=0;i<6;i++)if(!c.isNull(i))r.put(c.getColumnName(i),i<2?c.getLong(i):c.getString(i));rows.put(r);}}for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optString("ns").equals("reset"))reset=true;if(rows.length()>200){reset=true;rows=new JSONArray();}db.delete("ui_changes","seq<?",new String[]{""+Math.max(0,rev-4000)});return new JSONObject().put("revision",rev).put("reset",reset).put("rows",rows);}
 public JSONObject home(long anchor,String mode)throws Exception{return home(anchor,mode,true,true);}
 public JSONObject home(long anchor,String mode,boolean quick,boolean summary)throws Exception{SQLiteDatabase db=helper.getReadableDatabase();long now=System.currentTimeMillis();db.beginTransactionNonExclusive();try{JSONObject out=new JSONObject();Map<String,JSONObject> totals=new HashMap<>();for(String m:new String[]{"day","week","selected"}){if(m.equals("selected")?!summary:!quick){out.put(m,JSONObject.NULL);continue;}long[] r=LedgerStats.range(m.equals("selected")?anchor:now,LedgerStats.mode(m.equals("selected")?mode:m),true,now);String key=r[0]+"|"+r[1];JSONObject value=totals.get(key);if(value==null){value=LedgerStats.json(db,r[0],r[1]);totals.put(key,value);}out.put(m,value);}out.put("pending",DatabaseUtils.longForQuery(db,"SELECT count(*) FROM entries WHERE status='review'",null));out.put("revision",revision(db));db.setTransactionSuccessful();return out;}finally{db.endTransaction();}}
 public JSONObject select(JSONObject q)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();String scope=q.optString("scope","book"),t=token+scope,mode=q.getString("mode");if(!scope.equals("book")&&!scope.equals("review"))throw new JSONException("选择范围错误");db.beginTransaction();try{
  if(mode.equals("clear"))db.delete("ui_selection","token=?",new String[]{t});
  else{Filter f=new Filter(q.getJSONObject("filter"));String where=f.where;List<String> args=new ArrayList<>(f.args);if(q.has("id")){where+=" AND _id=?";args.add(""+q.getLong("id"));}String sub="SELECT _id FROM entries WHERE "+where;
   boolean remove=mode.equals("toggle")&&DatabaseUtils.longForQuery(db,"SELECT count(*) FROM entries WHERE "+where+" AND _id NOT IN (SELECT id FROM ui_selection WHERE token=?)",append(args,t))==0;
   if(remove)db.execSQL("DELETE FROM ui_selection WHERE token=? AND id IN ("+sub+")",prepend(t,args));else{if(mode.equals("all"))db.delete("ui_selection","token=?",new String[]{t});db.execSQL("INSERT OR IGNORE INTO ui_selection SELECT ?,v.id,v.rev FROM ui_version v WHERE v.id IN ("+sub+")",prepend(t,args));}
  }
  JSONObject result=selection(scope);db.setTransactionSuccessful();return result;
 }finally{db.endTransaction();}}
 static String[] append(List<String> a,String b){List<String> x=new ArrayList<>(a);x.add(b);return x.toArray(new String[0]);}static Object[] prepend(String a,List<String> b){List<Object> x=new ArrayList<>();x.add(a);x.addAll(b);return x.toArray();}
 public JSONObject selection(String scope)throws JSONException{SQLiteDatabase db=helper.getReadableDatabase();return new JSONObject().put("count",DatabaseUtils.longForQuery(db,"SELECT count(*) FROM ui_selection WHERE token=?",new String[]{token+scope}));}
 public int apply(String scope,String action,String category)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();String t=token+scope;int count=0;db.beginTransaction();try{
  long stale=DatabaseUtils.longForQuery(db,"SELECT count(*) FROM ui_selection s LEFT JOIN ui_version v ON v.id=s.id WHERE s.token=? AND (v.id IS NULL OR v.rev<>s.rev)",new String[]{t});if(stale>0)throw new JSONException("所选记录已变化，请重新选择；本次未修改");
  // Fixed chunks inside one transaction: no 5000-row cap or all-ID transport.
  long after=0;while(true){JSONArray ids=new JSONArray();try(Cursor c=db.rawQuery("SELECT id FROM ui_selection WHERE token=? AND id>? ORDER BY id LIMIT 400",new String[]{t,""+after})){while(c.moveToNext()){after=c.getLong(0);ids.put(after);}}if(ids.length()==0)break;count+=scope.equals("review")?helper.reviewBatch(ids,action):helper.batch(ids,action,category);}
  db.delete("ui_selection","token=?",new String[]{t});db.setTransactionSuccessful();
 }finally{db.endTransaction();}helper.notifyChanged();return count;}
 public int tagSelected(String tag)throws Exception{SQLiteDatabase db=helper.getWritableDatabase();JSONObject t=FinanceData.get(db,tag);if(t==null||!t.getString("type").equals("tag"))throw new IllegalArgumentException("标签不存在");String scope=token+"book";if(FinanceData.number(db,"SELECT count(*) FROM ui_selection s LEFT JOIN ui_version v ON v.id=s.id WHERE s.token=? AND (v.id IS NULL OR v.rev<>s.rev)",scope)>0)throw new IllegalArgumentException("所选账单已变化，请重新选择");int count=0;try(Cursor c=db.rawQuery("SELECT id FROM ui_selection WHERE token=? ORDER BY id",new String[]{scope})){JSONArray chunk=new JSONArray();while(c.moveToNext()){chunk.put(c.getLong(0));if(chunk.length()==400){FinanceData.mutate(db,"taglink",new JSONObject().put("tag",tag).put("entries",chunk));count+=chunk.length();chunk=new JSONArray();}}if(chunk.length()>0){FinanceData.mutate(db,"taglink",new JSONObject().put("tag",tag).put("entries",chunk));count+=chunk.length();}}return count;}
 public void close(){helper.getWritableDatabase().delete("ui_selection","token LIKE ?",new String[]{token+"%"});delivered.clear();}
}
